import com.hrm.HrmApplication;import com.hrm.service.provider.*;import com.hrm.service.engine.*;import org.springframework.boot.SpringApplication;import org.springframework.beans.factory.support.BeanDefinitionRegistry;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.aop.support.AopUtils;import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;import java.util.*;import java.nio.file.*;import tools.jackson.databind.json.JsonMapper;
public class QaBackendLauncher {
 public static void main(String[] args)throws Exception {
  var app=new SpringApplication(HrmApplication.class);
  app.addInitializers(context->context.addBeanFactoryPostProcessor(factory->{String name="org.springframework.context.annotation.internalScheduledAnnotationProcessor";if(factory.containsBeanDefinition(name))((BeanDefinitionRegistry)factory).removeBeanDefinition(name);}));
  var context=app.run(args);var db=context.getBean(JdbcTemplate.class);String database=db.queryForObject("SELECT DB_NAME()",String.class);if(!"hrm_test".equals(database)){context.close();throw new IllegalStateException("QA requires hrm_test");}
  var routes=new ArrayList<Object>();context.getBean(RequestMappingHandlerMapping.class).getHandlerMethods().forEach((info,method)->routes.add(Map.of("paths",info.getPatternValues(),"methods",info.getMethodsCondition().getMethods(),"controller",method.getBeanType().getSimpleName(),"handler",method.getMethod().getName())));
  var evidence=new LinkedHashMap<String,Object>();evidence.put("database",database);evidence.put("profiles",context.getEnvironment().getActiveProfiles());evidence.put("salaryProvider",AopUtils.getTargetClass(context.getBean(SalaryContractProvider.class)).getName());evidence.put("attendanceProvider",AopUtils.getTargetClass(context.getBean(AttendanceDataProvider.class)).getName());evidence.put("calculationEngine",AopUtils.getTargetClass(context.getBean(PayrollCalculationEngine.class)).getName());evidence.put("automaticSchedulers","suppressed by QA-only launcher; job beans may be invoked separately");evidence.put("routes",routes);
  Files.writeString(Path.of(System.getenv("QA_RUNTIME_EVIDENCE")),JsonMapper.builder().build().writerWithDefaultPrettyPrinter().writeValueAsString(evidence));
 }
}
